const SBX=156;
/* ---------- picture icons (Sketch3D asset pack) ---------- */
const IMGS={"front":"","savebig":"","select":"","erase":"","reshape":"","size":"","turn":"","draw":"","limb":"","eyes":"","smile":"","crease":"","circle":"","box":"","star":"","heart":"","egg":"","capsule":"","triangle":"","drop":"","moon":"","holeC":"","holeB":"","fill":"","colour":"","views":"","camera":"","side":"","reset":"","undo":"","redo":"","save":"","logo":""};
const SK_TOOL={select:'select',erase:'erase',draw:'draw',limb:'limb',eyes:'eyes',smile:'smile',crease:'crease',circle:'circle',box:'box',star:'star',heart:'heart',egg:'egg',capsule:'capsule',triangle:'triangle',drop:'drop',moon:'moon',holeC:'holeC',holeB:'holeB',fill:'fill',reshape:'reshape'};
const SK_ID={railScale:'size',railRot:'turn',vScale:'size',vRot:'turn',vFocus:'camera',undo:'undo',redo:'redo',scUndo:'undo',scRedo:'redo',expBtn:'savebig'};
function skImg(k,cls){const i=new Image();i.className=cls||'ic';i.alt='';i.draggable=false;i.src='data:image/webp;base64,'+IMGS[k];return i}
function skSwap(el,k,sel){if(!el||!k||!IMGS[k])return;const s=el.querySelector(sel||':scope > svg.i');if(!s)return;s.replaceWith(skImg(k))}
const MULTI_SVG="data:image/svg+xml;utf8,"+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 91"><rect x="3" y="3" width="90" height="85" rx="22" fill="#7cc6f2" stroke="#3b6f99" stroke-width="5"/><rect x="18" y="17" width="34" height="34" rx="8" fill="#fff" stroke="#2b4f73" stroke-width="5"/><rect x="42" y="38" width="34" height="34" rx="8" fill="#ffd54a" stroke="#2b4f73" stroke-width="5"/></svg>');
function skMulti(){const g=document.querySelector('#tools .tgroup.g0');if(!g||g.querySelector('#multiBtn'))return;const b=document.createElement('button');b.type='button';b.className='tool';b.id='multiBtn';b.title='Pick several parts: tap each one, or hold Shift';b.setAttribute('aria-pressed',multiOn?'true':'false');b.style.setProperty('--tc','#2563eb');const i=new Image();i.className='ic';i.alt='';i.draggable=false;i.src=MULTI_SVG;b.appendChild(i);b.appendChild(document.createTextNode('Multi'));
 b.onclick=()=>{multiOn=!multiOn;b.setAttribute('aria-pressed',multiOn?'true':'false');if(multiOn){if(tool!=='select'&&typeof setTool==='function')setTool('select');toast('Multi-select on. Tap parts to add or remove them.')}else toast('Multi-select off.')};
 const sb=g.querySelector('[data-t="select"]');if(sb&&sb.nextSibling)g.insertBefore(b,sb.nextSibling);else g.appendChild(b)}
function skinAll(){skMulti();
 document.querySelectorAll('.tool[data-t]').forEach(b=>skSwap(b,SK_TOOL[b.dataset.t]));
 for(const id in SK_ID)skSwap(document.getElementById(id),SK_ID[id]);
 skSwap(document.querySelector('#viewSeg [data-v="side"]'),'side');skSwap(document.querySelector('#viewSeg [data-v="front"]'),'front');
 skSwap(document.querySelector('.vchome'),'reset');
 const vm=document.getElementById('vMenuBtn');if(vm&&!vm.querySelector('img.ic'))vm.insertBefore(skImg('views'),vm.firstChild);
 const br=document.querySelector('.brand');if(br&&!br.querySelector('img.logo')){br.setAttribute('aria-label','Sketch3D');br.textContent='';const l=skImg('logo','logo');l.alt='Sketch3D';br.appendChild(l)}}
{let sk=0;const run=()=>{sk=0;skinAll()};skinAll();const root=document.getElementById('app');if(root&&window.MutationObserver)new MutationObserver(()=>{if(!sk)sk=requestAnimationFrame(run)}).observe(root,{childList:true,subtree:true})}
